int drm_create_virtual_surface(struct drm_device *dev, void *data,
                               struct drm_file *file_priv) {
    struct drm_virtual_surface_create_args *args = data;
    struct drm_virtual_surface *surface;
    int ret = -EINVAL;

    if (!dev || !data || !file_priv || !args->width || !args->height)
        return -EINVAL;

    surface = kzalloc(sizeof(*surface), GFP_KERNEL);
    if (!surface)
        return -ENOMEM;

    surface->width = args->width;
    surface->height = args->height;
    surface->format = args->format;
    surface->modifier = args->modifier;

    ret = drm_gem_object_init(dev, &surface->gem, args->size);
    if (ret) {
        kfree(surface);
        return ret;
    }

    surface->backup = kzalloc(args->size, GFP_KERNEL);
    if (!surface->backup) {
        drm_gem_object_release(&surface->gem);
        kfree(surface);
        return -ENOMEM;
    }

    args->handle = surface->gem.handle;
    args->pitch = surface->pitch;
    args->size = surface->gem.size;

    drm_gem_add(&surface->gem);

    return 0;
}

