int create_graphics_buffer_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    struct surface_creation_args *args = data;
    struct graphics_surface *surface = NULL;
    int ret = -EINVAL;

    if (!dev || !args || !file_priv) {
        goto cleanup;
    }

    surface = kzalloc(sizeof(*surface), GFP_KERNEL);
    if (!surface) {
        ret = -ENOMEM;
        goto cleanup;
    }

    ret = allocate_surface_resources(surface, args->width, args->height, args->format);
    if (ret < 0) {
        goto cleanup;
    }

    ret = initialize_surface(surface, args->flags);
    if (ret < 0) {
        goto cleanup;
    }

    ret = setup_surface_backups(surface);
    if (ret < 0) {
        goto cleanup;
    }

    args->surface_id = surface->id;
    args->handle = drm_gem_handle_create(file_priv, &surface->gem_obj, &args->handle_out);

    ret = 0;

cleanup:
    if (ret < 0 && surface) {
        release_surface(surface);
        kfree(surface);
    }

    return ret;
}

int create_graphics_buffer_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    struct surface_creation_args *args = data;
    struct graphics_surface *surface;
    int ret = 0;

    if (!dev || !args || !file_priv)
        return -EINVAL;

    surface = kzalloc(sizeof(*surface), GFP_KERNEL);
    if (!surface)
        return -ENOMEM;

    ret = allocate_surface_resources(surface, args);
    if (ret < 0)
        goto error_free_surface;

    ret = init_surface_with_arguments(surface, args);
    if (ret < 0)
        goto error_free_resources;

    ret = setup_backup_memory(surface);
    if (ret < 0)
        goto error_cleanup_surface;

    args->surface_id = assign_unique_surface_id(surface);
    args->handle = get_surface_handle(surface);

    return 0;

error_cleanup_surface:
    cleanup_surface(surface);
error_free_resources:
    free_surface_resources(surface);
error_free_surface:
    kfree(surface);
    return ret;
